import sys
from collections import defaultdict

def max_sum_split(n, d):
    prefix_sums = defaultdict(list)
    total_sum = 0
    max_sum = 0

    for i in range(n):
        total_sum += d[i]
        prefix_sums[total_sum].append(i)

    for i in range(n):
        total_sum -= d[i]

        if total_sum in prefix_sums:
            for j in prefix_sums[total_sum]:
                if j < i:
                    max_sum = max(max_sum, total_sum)

    return max_sum

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    d = list(map(int, data[1:]))

    result = max_sum_split(n, d)
    print(result)

if __name__ == "__main__":
    main()
